"use client";

import React, { createContext, useEffect, useState, ReactNode } from "react";

import { AuthService } from "@/application/auth/AuthService";
import { FirebaseAuthClient } from "@/infrastructure/auth/FirebaseAuthClient";
import { LaravelAuthApi } from "@/infrastructure/auth/LaravelAuthApi";
import { createHttpClient } from "@/infrastructure/auth/HttpClient";
import { TokenRefreshService } from "@/application/auth/TokenRefreshService";
import { AuthUser } from "@/domain/auth/AuthUser";

export const AuthContext = createContext<any>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [services, setServices] = useState<{
    authService: AuthService;
    laravelApi: LaravelAuthApi;
    refreshService: TokenRefreshService;
  } | null>(null);

  const [user, setUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // -------------------------------------------------------------
  // ① 初回にサービス初期化（Hook は必ず実行される）
  // -------------------------------------------------------------
  useEffect(() => {
    const firebase = new FirebaseAuthClient();
    let laravel: LaravelAuthApi;
    let refresh: TokenRefreshService;

    const refreshCallback = async (): Promise<void> => {
      const refreshed = await refresh.refresh();
      setUser(refreshed || null);
    };

    const httpClient = createHttpClient(refreshCallback);

    laravel = new LaravelAuthApi(httpClient);
    const auth = new AuthService(firebase, laravel);
    refresh = new TokenRefreshService(laravel);

    setServices({
      authService: auth,
      laravelApi: laravel,
      refreshService: refresh,
    });
  }, []);

  // -------------------------------------------------------------
  // ② services が初期化されてから /me を実行
  // -------------------------------------------------------------
  useEffect(() => {
    if (!services) return; // Hook は呼び出されるが、内部で早期 return はOK

    (async () => {
      try {
        const u = await services.laravelApi.me();
        setUser(u);
      } catch {
        setUser(null);
      } finally {
        setIsLoading(false);
      }
    })();
  }, [services]);

  // -------------------------------------------------------------
  // ③ 認証関連メソッド
  // -------------------------------------------------------------
  async function register({
    name,
    email,
    password,
  }: {
    name: string;
    email: string;
    password: string;
  }) {
    return services?.authService.register(name, email, password);
  }

  async function login({
    email,
    password,
  }: {
    email: string;
    password: string;
  }) {
    if (!services) return;
    setIsLoading(true);
    const u = await services.authService.login(email, password);
    setUser(u);
    setIsLoading(false);
  }

  async function logout() {
    if (!services) return;
    await services.authService.logout();
    setUser(null);
  }

  async function reloadUser() {
    if (!services) return;
    try {
      const u = await services.laravelApi.me();
      setUser(u);
    } catch {
      setUser(null);
    }
  }

  // -------------------------------------------------------------
  // ④ UI 描画（services が null の間はロード画面を返す）
  // -------------------------------------------------------------
  if (!services) {
    return <div className="text-center p-10">Loading Auth Services...</div>;
  }

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isLoading,
        register,
        login,
        logout,
        reloadUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}
